--header 'Authorization: ESA c2FtcGxlU2VydmljZVNlY3JldDpzYW1wbGVMaWNlbnNlS2V5' \
--header 'Content-Type: application/json' \
--data-raw '{
  "children": [
    {
      "categoryId": "1",
      "children": [
        {
          "categoryId": "3"
        },
        {
          "categoryId": "4"
        }
      ]
    },
    {
      "categoryId": "2"
    }
  ]
}'
Response in JSON format (Status: 204 No Content)
